    if(!force&&Date.now()-state.aqiGridFetchedAt<35000)return;
    const b=state.map.getBounds();const payload={west:b.getWest(),south:b.getSouth(),east:b.getEast(),north:b.getNorth(),zoom:state.map.getZoom()};
    const key=[payload.west,payload.south,payload.east,payload.north].map(v=>Number(v).toFixed(1)).join(':')+':'+Math.floor(payload.zoom);
