  function normalizedSearchBounds(hit){
    const e=hit?.extent||hit?.boundingbox||null;if(!Array.isArray(e)||e.length<4)return null;
    const n=e.map(Number);if(n.some(v=>!Number.isFinite(v)))return null;
    const west=Math.min(n[0],n[2]),east=Math.max(n[0],n[2]),south=Math.min(n[1],n[3]),north=Math.max(n[1],n[3]);
    if(east-west>300||north-south>160||south < -90||north > 90||west < -180||east > 180)return null;
    return [[west,south],[east,north]];
  }
