  function aiContext(){const nearby=state.selected?nearestEvidence(state.selected.lat,state.selected.lon).slice(0,5):[];const facts=nearby.map(x=>`${x.info.source}: ${x.info.name}; ${x.info.detail}; ${Math.round(x.distance)} km from selected coordinate; time ${x.info.time||'not provided'}; source ${x.info.url}`);(state.latestNews||[]).slice(0,3).forEach(a=>facts.push(`Unverified news-index result: ${a.title}; publisher ${a.domain}; date ${a.seendate}; URL ${a.url}`));const d=state.currentWeather||{},c=d.current||{},daily=d.daily||{};const forecast=(daily.time||[]).slice(0,7).map((date,i)=>`${date}: ${weatherCodeName(daily.weather_code?.[i]??'—')}, max ${daily.temperature_2m_max?.[i]??'—'}C/min ${daily.temperature_2m_min?.[i]??'—'}C, rain chance ${daily.precipitation_probability_max?.[i]??'—'}%, precip ${daily.precipitation_sum?.[i]??'—'}mm`).join(' | ');return {selected_place:state.selected?.name||'Global view',coordinates:state.selected?{lat:state.selected.lat,lon:state.selected.lon}:null,local_time:state.placeTimezone?new Intl.DateTimeFormat('en-US',{timeZone:state.placeTimezone,dateStyle:'medium',timeStyle:'short'}).format(new Date())+' ('+state.placeTimezone+')':'unknown',weather_summary:state.currentWeather?.current?`Open-Meteo forecast/model current: ${c.temperature_2m} C; ${weatherCodeName(c.weather_code)}; humidity ${c.relative_humidity_2m}%; wind ${c.wind_speed_10m} km/h; precip ${c.precipitation} mm; source/model time ${c.time}; timezone ${d.timezone||'unknown'}. Seven-day forecast: ${forecast}`:'No weather record currently loaded',crop_screening:state.cropSummary||'No crop weather-fit screen computed yet; do not assume a crop is suitable.',selected_event:state.selected?.kind!=='location'?`${state.selected?.source||''}: ${state.selected?.name||''}; ${state.selected?.detail||''}; time ${state.selected?.time||''}`:'',source_facts:facts};}
  function guessPlaceFromQuestion(question){
    const q=String(question||'').trim();if(!q)return '';
    const stop=new Set(['today','tomorrow','yesterday','now','currently','current','happening','open','show','take','please','weather','rain','raining','rainfall','sunny','temperature','forecast','will','be','is','are','what','when','where','how','tell','please','about','whether','chance','chances','barish','baarish','barsaat','hoga','hogi','hai','ka','ki','ke','mein','me','ma','ko','aaj','kal','mausam','batao','bataeya','bataye','bataiye','kya','ugana','ugau','achha','accha','hona','बारे','में','का','की','के','को','आज','कल','बारिश','वर्षा','मौसम','बताइए','बताओ','होगा','होगी','क्या','कैसा','कैसी','है']);
    const cleanCandidate=(raw)=>{const words=String(raw||'').replace(/[?!.,;:]+/g,' ').trim().split(/\s+/u);const out=[];for(const w of words){const norm=w.toLocaleLowerCase().replace(/[।,?!]+$/u,'');if(stop.has(norm)||['currently','right','now','please','today','tomorrow','currently','happening','weather','forecast','floods','flood','earthquake','earthquakes','news','information','info','details','map','pin','location','place'].includes(norm))break;if(out.length>=4)break;if(w.length>1)out.push(w);}return out.join(' ').replace(/\s+/g,' ').trim();};
    // Handle direct navigation commands and voice-style short phrases.
    let direct=q.replace(/^(?:please\s+)?(?:open|show|find|locate|pin|navigate to|go to|take me to|zoom to|zoom into|tell me about|what is|what's|what are|where is|where's)\s+/iu,'').trim();
    if(direct && direct.length>=3 && !/\b(?:flood|floods|earthquake|earthquakes|weather|recipe|food|news|happening|currently|today|tomorrow|rain|forecast)\b/iu.test(direct) && direct.split(/\s+/u).length<=4){const c=cleanCandidate(direct);if(c.length>=3)return c;}
    let m=q.match(/\b(?:in|at|near|around|over|for|about|within)\s+([\p{L}\p{M}][\p{L}\p{M}.'’\-]*(?:\s+[\p{L}\p{M}][\p{L}\p{M}.'’\-]*){0,3})/iu);
    if(m){const c=cleanCandidate(m[1]);if(c.length>=3)return c;}
    m=q.match(/([\p{L}\p{M}][\p{L}\p{M}.'’\-]*(?:\s+[\p{L}\p{M}][\p{L}\p{M}.'’\-]*){0,2})\s+(?:ke\s+baare\s+mein|ka\s+barema|ka\s+baare\s+mein|ko\s+mausam|का\s+बारे\s+में|के\s+बारे\s+में|के\s+मौसम|को\s+मौसम|mein|me|ma|ka|ki|ke|का|की|के|में|मा)\b/iu);
    if(m){const c=cleanCandidate(m[1]);if(c.length>=3)return c;}
    // Also handle short voice questions that start with a place, e.g. "Biratnagar aaj barish hogi?".
    m=q.match(/^([\p{L}\p{M}][\p{L}\p{M}.'’\-]*(?:\s+[\p{L}\p{M}][\p{L}\p{M}.'’\-]*){0,2})\s+(?:(?:aaj|today|tomorrow|barish|baarish|weather|rain|mausam|आज|बारिश|मौसम|को|का|की|के|में)\b)/iu);
    if(m){const c=cleanCandidate(m[1]);if(c.length>=3)return c;}
    return '';
  }
  async function resolvePlaceFromQuestion(question){
    const candidate=guessPlaceFromQuestion(question);if(!candidate)return '';
    if(state.selected&&state.selected.name&&state.selected.name.toLocaleLowerCase().includes(candidate.toLocaleLowerCase()))return '';
    try{const r=await api('geocode',{q:candidate});const hits=Array.isArray(r.data)?r.data:[];if(!hits.length)return `I couldn't resolve “${candidate}” to a place. I kept the current map selection; please search the intended place if that is wrong.`;const hit=hits[0];await goLocation(Number(hit.lon),Number(hit.lat),hit.display_name||hit.name||candidate);return `I changed the map context to ${hit.display_name||hit.name||candidate}.`;}
    catch(e){return `I couldn't load ${candidate} right now, so the answer may use the current map selection. Search for the place manually to ensure local context.`;}
  }
