  const cropPhotoCache=new Map();
  let cropPhotoObserver=null;
  const cropPhotoQueue=[]; let cropPhotoActive=0; const cropPhotoConcurrency=3;
  function pumpCropPhotoQueue(){
    while(cropPhotoActive<cropPhotoConcurrency&&cropPhotoQueue.length){
      const img=cropPhotoQueue.shift();
      if(!img||!img.isConnected){if(img)img.dataset.photoQueued='';continue;}
      cropPhotoActive++;
      hydrateOneCropPhoto(img).catch(()=>{}).finally(()=>{cropPhotoActive--;pumpCropPhotoQueue();});
    }
  }
  function enqueueCropPhoto(img){if(!img||!img.isConnected||img.dataset.photoLoaded==='1'||img.dataset.photoQueued==='1')return;img.dataset.photoQueued='1';cropPhotoQueue.push(img);pumpCropPhotoQueue();}
  async function hydrateOneCropPhoto(img){
    if(!img||!img.isConnected||img.dataset.photoLoaded==='1')return;
    img.dataset.photoQueued=''; img.dataset.photoLoaded='1';
    const name=(img.dataset.cropName||'').trim(),scientific=(img.dataset.cropScientific||'').trim();
    const key=(name+'|'+scientific).toLowerCase();
    const unavailable=img.parentElement?.querySelector('[data-photo-unavailable]');
    const sourceLink=img.parentElement?.querySelector('[data-crop-photo-source]');
    const credit=img.closest('.crop-tile')?.querySelector('[data-crop-photo-credit]');
    try{
      let photo=cropPhotoCache.get(key);
      if(photo===undefined){
        const result=await api('crop-photo',{name,scientific_name:scientific});
        photo=result.data?.photo||null;cropPhotoCache.set(key,photo);
      }
      if(!img.isConnected)return;
      if(!photo){img.hidden=true;if(unavailable){unavailable.hidden=false;unavailable.textContent='Species-matched photograph unavailable';}if(credit){credit.hidden=false;credit.textContent='No matching photo returned; no substitute image used.';}return;}
      img.alt=`${name} photograph: ${photo.title}. Creator: ${photo.creator}. Licence: ${photo.license}.`;
      img.referrerPolicy='no-referrer';
      img.addEventListener('load',()=>{img.classList.add('photo-loaded');if(unavailable)unavailable.hidden=true;},{once:true});
      img.addEventListener('error',()=>{img.hidden=true;if(unavailable){unavailable.hidden=false;unavailable.textContent='Photograph could not be loaded';}},{once:true});
      img.src=photo.thumbnail_url;
      if(sourceLink){sourceLink.href=photo.page_url;sourceLink.title=`${photo.title} · ${photo.creator} · ${photo.license}`;sourceLink.textContent='View photo source ↗';sourceLink.hidden=false;}
      if(credit){credit.hidden=false;credit.textContent=`${photo.creator||'Creator not listed'} · ${photo.license||'Review licence'}`;credit.title=`${photo.title} — open the photograph source for full terms.`;}
    }catch(error){
      if(img.isConnected){img.hidden=true;if(unavailable){unavailable.hidden=false;unavailable.textContent='Photo source unavailable';}if(credit){credit.hidden=false;credit.textContent='Photo search unavailable; no generic substitute shown.';}}
    }
  }
  function hydrateCropPhotos(){
    const imgs=[...document.querySelectorAll('img[data-crop-photo]')].filter(img=>img.dataset.photoLoaded!=='1');
    if(!imgs.length)return;
    if(!('IntersectionObserver'in window)){
      imgs.slice(0,12).forEach(enqueueCropPhoto);
      return;
    }
    if(!cropPhotoObserver)cropPhotoObserver=new IntersectionObserver(entries=>{
      entries.forEach(entry=>{if(!entry.isIntersecting)return;cropPhotoObserver.unobserve(entry.target);enqueueCropPhoto(entry.target);});
    },{root:null,rootMargin:'240px 0px',threshold:0.01});
    imgs.forEach(img=>cropPhotoObserver.observe(img));
  }
  window.EARTHSCOPE_HYDRATE_CROP_PHOTOS=hydrateCropPhotos;
