  function playTone(freq=440,duration=.16,pan=0){const ac=ensureAudio();if(!ac)return;const osc=ac.createOscillator(),gain=ac.createGain(),panner=ac.createStereoPanner?ac.createStereoPanner():null;osc.type='sine';osc.frequency.setValueAtTime(clamp(freq,140,1200),ac.currentTime);gain.gain.setValueAtTime(.0001,ac.currentTime);gain.gain.exponentialRampToValueAtTime(.045,ac.currentTime+.02);gain.gain.exponentialRampToValueAtTime(.0001,ac.currentTime+duration);if(panner){panner.pan.value=clamp(pan,-1,1);osc.connect(gain);gain.connect(panner);panner.connect(ac.destination)}else{osc.connect(gain);gain.connect(ac.destination)}osc.start();osc.stop(ac.currentTime+duration+.02);}
